/// Petit avatar rond de Titelive, avec l'initiale « T » sur vert anis en ultime repli.
struct TiteliveAvatarView: View {
    var size: CGFloat = 14

    var body: some View {
        Group {
            if let img = TiteliveAvatar.image {
                Image(nsImage: img).resizable().interpolation(.high).scaledToFill()
            } else {
                Text("T")
                    .font(.system(size: size * 0.55, weight: .bold, design: .rounded))
                    .foregroundStyle(Color(red: 0x12 / 255, green: 0x12 / 255, blue: 0x12 / 255))
            }
        }
        .frame(width: size, height: size)
        .background(Color(red: 0xCE / 255, green: 0xF9 / 255, blue: 0x82 / 255), in: Circle())
        .clipShape(Circle())
        .accessibilityHidden(true)
    }
}
